func (fx *FreightServiceSiteTestSuiteConfig) testBatchGet(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if provided parent is invalid.
	t.Run("invalid parent", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
			Parent: "invalid resource name",
			Names:  []string{},
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Method should fail with InvalidArgument if no names are provided.
	t.Run("names missing", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
			Parent: parent,
			Names:  []string{},
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Method should fail with InvalidArgument if a provided name is not valid.
	t.Run("invalid names", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
			Parent: parent,
			Names: []string{
				"invalid resource name",
			},
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Method should fail with InvalidArgument if a provided name only contains wildcards (-)
	t.Run("wildcard name", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
			Parent: parent,
			Names: []string{
				"shippers/-/sites/-",
			},
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	{
		parent := fx.nextParent(t, false)
		created00 := fx.create(t, parent)
		created01 := fx.create(t, parent)
		created02 := fx.create(t, parent)
		// Resources should be returned without errors if they exist.
		t.Run("all exists", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
				Parent: parent,
				Names: []string{
					created00.Name,
					created01.Name,
					created02.Name,
				},
			})
			assert.NilError(t, err)
			assert.DeepEqual(
				t,
				[]*v1.Site{
					created00,
					created01,
					created02,
				},
				response.Sites,
				protocmp.Transform(),
			)
		})

		// The method must be atomic; it must fail for all resources
		// or succeed for all resources (no partial success).
		t.Run("atomic", func(t *testing.T) {
			fx.maybeSkip(t)
			_, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
				Parent: parent,
				Names: []string{
					created00.Name,
					fx.notFoundName(created01.Name),
					created02.Name,
				},
			})
			assert.Equal(t, v2.CodeNotFound, v2.CodeOf(err), err)
		})

		// If a caller sets the "parent", and the parent collection in the name of any resource
		// being retrieved does not match, the request must fail.
		t.Run("parent mismatch", func(t *testing.T) {
			fx.maybeSkip(t)
			_, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
				Parent: fx.peekNextParent(t),
				Names: []string{
					created00.Name,
				},
			})
			assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
		})

		// The order of resources in the response must be the same as the names in the request.
		t.Run("ordered", func(t *testing.T) {
			fx.maybeSkip(t)
			for _, order := range [][]*v1.Site{
				{created00, created01, created02},
				{created01, created00, created02},
				{created02, created01, created00},
			} {
				response, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
					Parent: parent,
					Names: []string{
						order[0].GetName(),
						order[1].GetName(),
						order[2].GetName(),
					},
				})
				assert.NilError(t, err)
				assert.DeepEqual(t, order, response.Sites, protocmp.Transform())
			}
		})

		// If a caller provides duplicate names, the service should return
		// duplicate resources.
		t.Run("duplicate names", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().BatchGetSites(fx.Context(), &v1.BatchGetSitesRequest{
				Parent: parent,
				Names: []string{
					created00.Name,
					created00.Name,
				},
			})
			assert.NilError(t, err)
			assert.DeepEqual(
				t,
				[]*v1.Site{
					created00,
					created00,
				},
				response.Sites,
				protocmp.Transform(),
			)
		})

	}
}

func (fx *FreightServiceSiteTestSuiteConfig) testUpdate(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if no name is provided.
	t.Run("missing name", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		msg := fx.Update(parent)
		msg.Name = ""
		_, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
			Site: msg,
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Method should fail with InvalidArgument if provided name is not valid.
	t.Run("invalid name", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		msg := fx.Update(parent)
		msg.Name = "invalid resource name"
		_, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
			Site: msg,
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Field update_time should be updated when the resource is updated.
	t.Run("update time", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		updated, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
			Site: created,
		})
		assert.NilError(t, err)
		assert.Check(t, updated.UpdateTime.AsTime().After(created.UpdateTime.AsTime()))
	})

	// The updated resource should be persisted and reachable with Get.
	t.Run("persisted", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		updated, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
			Site: created,
		})
		assert.NilError(t, err)
		persisted, err := fx.Service().GetSite(fx.Context(), &v1.GetSiteRequest{
			Name: updated.Name,
		})
		assert.NilError(t, err)
		assert.DeepEqual(t, updated, persisted, protocmp.Transform())
	})

	// The field create_time should be preserved when a '*'-update mask is used.
	t.Run("preserve create_time", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		originalCreateTime := created.CreateTime
		updated, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
			Site: created,
			UpdateMask: &fieldmaskpb.FieldMask{
				Paths: []string{
					"*",
				},
			},
		})
		assert.NilError(t, err)
		assert.DeepEqual(t, originalCreateTime, updated.CreateTime, protocmp.Transform())
	})

	// Method should fail with Aborted if the supplied etag doesnt match the current etag value.
	t.Run("etag mismatch", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		msg := fx.Update(parent)
		msg.Name = created.Name
		msg.Etag = `"99999"`
		_, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
			Site: msg,
		})
		assert.Equal(t, v2.CodeAborted, v2.CodeOf(err), err)
	})

	// Field etag should have a new value when the resource is successfully updated.
	t.Run("etag updated", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		msg := fx.Update(parent)
		msg.Name = created.Name
		msg.Etag = created.Etag
		updated, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
			Site: msg,
		})
		assert.NilError(t, err)
		assert.Check(t, updated.Etag != created.Etag)
	})

	{
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		// Method should fail with NotFound if the resource does not exist.
		t.Run("not found", func(t *testing.T) {
			fx.maybeSkip(t)
			msg := fx.Update(parent)
			msg.Name = fx.notFoundName(created.Name)
			_, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
				Site: msg,
			})
			assert.Equal(t, v2.CodeNotFound, v2.CodeOf(err), err)
		})

		// The method should fail with InvalidArgument if the update_mask is invalid.
		t.Run("invalid update mask", func(t *testing.T) {
			fx.maybeSkip(t)
			_, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
				Site: created,
				UpdateMask: &fieldmaskpb.FieldMask{
					Paths: []string{
						"invalid_field_xyz",
					},
				},
			})
			assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
		})

		// Method should fail with InvalidArgument if any required field is missing
		// when called with '*' update_mask.
		t.Run("required fields", func(t *testing.T) {
			fx.maybeSkip(t)
			t.Run(".display_name", func(t *testing.T) {
				fx.maybeSkip(t)
				msg := proto.Clone(created).(*v1.Site)
				container := msg
				if container == nil {
					t.Skip("not reachable")
				}
				fd := container.ProtoReflect().Descriptor().Fields().ByName("display_name")
				container.ProtoReflect().Clear(fd)
				_, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
					Site: msg,
					UpdateMask: &fieldmaskpb.FieldMask{
						Paths: []string{
							"*",
						},
					},
				})
				assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
			})
			t.Run(".billing.billing_account", func(t *testing.T) {
				fx.maybeSkip(t)
				msg := proto.Clone(created).(*v1.Site)
				container := msg.GetBilling()
				if container == nil {
					t.Skip("not reachable")
				}
				fd := container.ProtoReflect().Descriptor().Fields().ByName("billing_account")
				container.ProtoReflect().Clear(fd)
				_, err := fx.Service().UpdateSite(fx.Context(), &v1.UpdateSiteRequest{
					Site: msg,
					UpdateMask: &fieldmaskpb.FieldMask{
						Paths: []string{
							"*",
						},
					},
				})
				assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
			})
		})

	}
}

func (fx *FreightServiceSiteTestSuiteConfig) testList(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if provided parent is invalid.
	t.Run("invalid parent", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
			Parent: "invalid resource name",
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Method should fail with InvalidArgument is provided page token is not valid.
	t.Run("invalid page token", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
			Parent:    parent,
			PageToken: "invalid page token",
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Method should fail with InvalidArgument is provided page size is negative.
	t.Run("negative page size", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
			Parent:   parent,
			PageSize: -10,
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	{
		const resourcesCount = 5
		parent := fx.nextParent(t, true)
		parentMsgs := make([]*v1.Site, resourcesCount)
		for i := 0; i < resourcesCount; i++ {
			parentMsgs[i] = fx.create(t, parent)
		}

		// If parent is provided the method must only return resources
		// under that parent.
		t.Run("isolation", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
				Parent:   parent,
				PageSize: 999,
			})
			assert.NilError(t, err)
			assert.DeepEqual(
				t,
				parentMsgs,
				response.Sites,
				cmpopts.SortSlices(func(a, b *v1.Site) bool {
					return a.Name < b.Name
				}),
				protocmp.Transform(),
			)
		})

		// If there are no more resources, next_page_token should not be set.
		t.Run("last page", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
				Parent:   parent,
				PageSize: resourcesCount,
			})
			assert.NilError(t, err)
			assert.Equal(t, "", response.NextPageToken)
		})

		// If there are more resources, next_page_token should be set.
		t.Run("more pages", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
				Parent:   parent,
				PageSize: resourcesCount - 1,
			})
			assert.NilError(t, err)
			assert.Check(t, response.NextPageToken != "")
		})

		// Listing resource one by one should eventually return all resources.
		t.Run("one by one", func(t *testing.T) {
			fx.maybeSkip(t)
			msgs := make([]*v1.Site, 0, resourcesCount)
			var nextPageToken string
			for {
				response, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
					Parent:    parent,
					PageSize:  1,
					PageToken: nextPageToken,
				})
				assert.NilError(t, err)
				assert.Equal(t, 1, len(response.Sites))
				msgs = append(msgs, response.Sites...)
				nextPageToken = response.NextPageToken
				if nextPageToken == "" {
					break
				}
			}
			assert.DeepEqual(
				t,
				parentMsgs,
				msgs,
				cmpopts.SortSlices(func(a, b *v1.Site) bool {
					return a.Name < b.Name
				}),
				protocmp.Transform(),
			)
		})

		// When listing resource with page size zero the service should use a default value.
		t.Run("page size zero", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
				Parent:   parent,
				PageSize: 0,
			})
			assert.NilError(t, err)
			// Server should use a default page size and return at least some results
			assert.Check(t, len(response.Sites) > 0, "expected server to return at least 1 resource with page_size=0")
		})

	}
	{
		const resourcesCount = 5
		parent := fx.nextParent(t, true)
		parentMsgs := make([]*v1.Site, resourcesCount)
		for i := 0; i < resourcesCount; i++ {
			parentMsgs[i] = fx.create(t, parent)
		}

		// Method should not return deleted resources.
		t.Run("deleted", func(t *testing.T) {
			fx.maybeSkip(t)
			const deleteCount = 3
			for i := 0; i < deleteCount; i++ {
				_, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
					Name: parentMsgs[i].Name,
					Etag: parentMsgs[i].Etag,
				})
				assert.NilError(t, err)
			}
			response, err := fx.Service().ListSites(fx.Context(), &v1.ListSitesRequest{
				Parent:   parent,
				PageSize: 9999,
			})
			assert.NilError(t, err)
			assert.DeepEqual(
				t,
				parentMsgs[deleteCount:],
				response.Sites,
				cmpopts.SortSlices(func(a, b *v1.Site) bool {
					return a.Name < b.Name
				}),
				protocmp.Transform(),
			)
		})

	}
}

func (fx *FreightServiceSiteTestSuiteConfig) testDelete(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if no name is provided.
	t.Run("missing name", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: "",
			Etag: "",
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Method should fail with InvalidArgument if the provided name is not valid.
	t.Run("invalid name", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: "invalid resource name",
			Etag: "",
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Resource should be deleted without errors if it exists.
	t.Run("exists", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		_, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: created.Name,
			Etag: created.Etag,
		})
		assert.NilError(t, err)
	})

	// Method should fail with NotFound if the resource does not exist.
	t.Run("not found", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		_, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: fx.notFoundName(created.Name),
			Etag: created.Etag,
		})
		assert.Equal(t, v2.CodeNotFound, v2.CodeOf(err), err)
	})

	// Method should fail with NotFound if the resource was already deleted. This also applies to soft-deletion.
	t.Run("already deleted", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		deleted, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: created.Name,
			Etag: created.Etag,
		})
		assert.NilError(t, err)
		_ = deleted
		_, err = fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: created.Name,
			Etag: deleted.Etag,
		})
		assert.Equal(t, v2.CodeNotFound, v2.CodeOf(err), err)
	})

	// Method should fail with InvalidArgument if the provided name only contains wildcards ('-')
	t.Run("only wildcards", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: "shippers/-/sites/-",
			Etag: "",
		})
		assert.Equal(t, v2.CodeInvalidArgument, v2.CodeOf(err), err)
	})

	// Method should fail with Aborted if the supplied etag doesnt match the current etag value.
	t.Run("etag mismatch", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		_, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: created.Name,
			Etag: `"99999"`,
		})
		assert.Equal(t, v2.CodeAborted, v2.CodeOf(err), err)
	})

	// A soft-deleted resource should have delete_time assigned.
	t.Run("soft-deleted delete_time", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		beforeDelete := time.Now()
		deleted, err := fx.Service().DeleteSite(fx.Context(), &v1.DeleteSiteRequest{
			Name: created.Name,
			Etag: created.Etag,
		})
		assert.NilError(t, err)
		assert.Check(t, deleted.DeleteTime.AsTime().After(beforeDelete))
	})

}

func (fx *FreightServiceSiteTestSuiteConfig) nextParent(t *testing.T, pristine bool) string {
	if pristine {
		fx.currParent++
	}
	if fx.currParent >= len(fx.Parents) {
		t.Fatal("need at least", fx.currParent+1, "parents")
	}
	return fx.Parents[fx.currParent]
}

func (fx *FreightServiceSiteTestSuiteConfig) peekNextParent(t *testing.T) string {
	next := fx.currParent + 1
	if next >= len(fx.Parents) {
		t.Fatal("need at least", next+1, "parents")
	}
	return fx.Parents[next]
}

func (fx *FreightServiceSiteTestSuiteConfig) maybeSkip(t *testing.T) {
	for _, skip := range fx.Skip {
		if strings.Contains(t.Name(), skip) {
			t.Skip("skipped because of .Skip")
		}
	}
}

func (fx *FreightServiceSiteTestSuiteConfig) create(t *testing.T, parent string) *v1.Site {
	t.Helper()
	userSetID := ""
	if fx.IDGenerator != nil {
		userSetID = fx.IDGenerator()
	}
	created, err := fx.Service().CreateSite(fx.Context(), &v1.CreateSiteRequest{
		Parent: parent,
		Site:   fx.Create(parent),
		SiteId: userSetID,
	})
	assert.NilError(t, err)
	return created
}

func (fx *FreightServiceSiteTestSuiteConfig) userSettableID(fallback string) string {
	if fx.IDGenerator != nil {
		return fx.IDGenerator()
	}
	return fallback
}

func (fx *FreightServiceSiteTestSuiteConfig) notFoundName(name string) string {
	if fx.IDGenerator != nil {
		// replacing the ID with a new one keeps the name valid for the service's ID format
		return name[:strings.LastIndex(name, "/")+1] + fx.IDGenerator()
	}
	// appending to the resource name ensures it is valid
	return name + "notfound"
}
